head.script:
/**
 * @component
 * @componentName udc_frame
 * @pluginName
 * @company
 * @developer
 * @category /ui/js
 * @notSupportBrowser
 * @version
 * @htmlRender
 * @icon
 * @disableIcon
 * @description
 * @width
 * @height
 * @license
 * @imagePath
 * @homepage
 */

scwin.FrameID = "";
scwin.srcUrl = "";
scwin.XPos = "";
scwin.YPos = "";
scwin.Width = "";
scwin.Height = "";

scwin.onpageload = function() {

};

/**
 * @method
 * @name path
 * @description
 * @param {string} path desc
 * @returns {scope} 
 * @hidden N
 * @exception
 * @example
 */ 
scwin.path = function(path) {
	// 1단계 부모 접근은 gcc 공통함수($c.win.getParent)로 위임하고, 다단은 $p 체인으로 확장한다.
	// (다단·/top 워킹은 대응 gcc 공통함수가 없어 어댑터에 유지 — browserPopup 자식 화면은 $c.win.getOpenerScope/callOpener 사용)
	if (path === "../../") {
		return $c.win.getParent().$p.parent();
	} else if (path === "../../../") {
		return $c.win.getParent().$p.parent().$p.parent();
	} else {
		return $c.win.getParent();   // "../" 및 그 외
	}
};

/**
 * @method
 * @name CreateDialogFrame
 * @description
 * @param {string} popupId desc
 * @param {string} popupUrl desc
 * @param {string} popTitle desc
 * @param {string} opts desc
 * @param {string} paramData desc
 * @example
 * @hidden N
 * @exception 
 */
scwin.CreateDialogFrame = async function(popupId, popupUrl, popTitle, opts, param) {
    const options = {
        id: popupId,
        popupName: popTitle,
        frameModal: "top",
    };

    opts = opts || {};
    if (typeof opts.width !== "undefined") {
        options.width = opts.width;
    }
    if (typeof opts.height !== "undefined") {
        options.height = opts.height;
    }

    return await $c.win.openPopup(popupUrl, options, param);
};

/**
 * @method
 * @name Provider
 * @description
 * @param {string} path
 * @hidden N
 * @exception
 * @example
 */ 
scwin.Provider = function(path) {
    let scopeObj;
    if (path == "/top") {
        return scopeObj = $p.top();
    }
    return $c.frame.path(path);
};

/**
 * @method
 * @name SetEvent
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.SetEvent = function() {
    return $p.top().$p;
};

/**
 * @method
 * @name FrameShow
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.FrameShow = function() {
    return $p.top().$p;
};

/**
 * @method
 * @name parent
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.parent = function() {
    return $p.top().$p;
};
